<?php
require_once __DIR__.'/config/database.php';
require_once __DIR__.'/lib/auth.php';

$pdo=db();
$token=trim((string)($_GET['token']??$_POST['token']??''));
$error='';$confirmed=false;$invitation=null;$slots=[];
if(!preg_match('/^[A-Za-z0-9_-]{40,60}$/',$token)){$error='This interview link is invalid.';http_response_code(404);}else{
 $find=$pdo->prepare("SELECT ii.*,ib.timezone,ib.status batch_status,c.name candidate_name,j.title job_title,s.starts_at confirmed_at FROM interview_invitations ii JOIN interview_batches ib ON ib.id=ii.batch_id JOIN candidates c ON c.id=ii.candidate_id JOIN jobs j ON j.id=ib.job_id LEFT JOIN interview_slots s ON s.id=ii.confirmed_slot_id WHERE ii.token_hash=? LIMIT 1");
 $find->execute([hash('sha256',$token)]);$invitation=$find->fetch();
 if(!$invitation){$error='This interview link is invalid.';http_response_code(404);}elseif($invitation['status']==='confirmed'){$confirmed=true;}elseif($invitation['batch_status']!=='active'||strtotime($invitation['expires_at'])<time()){$error='This interview link has expired. Please contact the hiring team.';}else{$slotStmt=$pdo->prepare("SELECT id,starts_at,ends_at FROM interview_slots WHERE batch_id=? AND status='available' AND starts_at>=NOW() ORDER BY starts_at");$slotStmt->execute([$invitation['batch_id']]);$slots=$slotStmt->fetchAll();}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&!$error&&!$confirmed){
 try{
  if(!verifyCsrf($_POST['csrf']??''))throw new RuntimeException('Your session expired. Refresh and try again.');
  $slotId=(int)($_POST['slot_id']??0);if(!$slotId)throw new RuntimeException('Choose an available interview time.');
  $pdo->beginTransaction();$lock=$pdo->prepare("SELECT id,starts_at FROM interview_slots WHERE id=? AND batch_id=? AND status='available' AND starts_at>=NOW() FOR UPDATE");$lock->execute([$slotId,$invitation['batch_id']]);$slot=$lock->fetch();$inviteLock=$pdo->prepare("SELECT status FROM interview_invitations WHERE id=? FOR UPDATE");$inviteLock->execute([$invitation['id']]);
  if($inviteLock->fetchColumn()!=='awaiting_confirmation')throw new RuntimeException('This invitation is no longer available.');if(!$slot)throw new RuntimeException('That time was just booked. Please choose another slot.');
  $pdo->prepare("UPDATE interview_slots SET status='reserved',invitation_id=?,reserved_at=NOW() WHERE id=?")->execute([$invitation['id'],$slotId]);$pdo->prepare("UPDATE interview_invitations SET status='confirmed',confirmed_slot_id=? WHERE id=?")->execute([$slotId,$invitation['id']]);$pdo->prepare("INSERT INTO audit_events(user_id,action,entity_type,entity_id,metadata_json) VALUES(NULL,'interview.slot_confirmed','interview_invitation',?,?)")->execute([(string)$invitation['id'],json_encode(['candidate_id'=>$invitation['candidate_id'],'slot_id'=>$slotId,'starts_at'=>$slot['starts_at'],'outcome'=>'success'])]);$pdo->commit();$invitation['confirmed_at']=$slot['starts_at'];$confirmed=true;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$grouped=[];foreach($slots as $slot)$grouped[substr($slot['starts_at'],0,10)][]=$slot;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Choose interview time | NonceBlox</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><style>:root{--ink:#171722;--muted:#737080;--line:#e9e7ef;--violet:#6f45ff;--soft:#f7f5ff;--green:#12875c}*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:Inter,Arial,sans-serif;color:var(--ink);background:radial-gradient(circle at 85% 10%,#ede8ff,transparent 28%),#f7f7fa;padding:32px 16px}.wrap{width:min(760px,100%);margin:auto}.brand{font-weight:800;font-size:20px;margin-bottom:22px}.card{background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 22px 60px #241c4610;overflow:hidden}.hero{padding:36px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,#fff,#f8f5ff)}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--violet);font-weight:700}h1{font-size:32px;letter-spacing:-.04em;margin:10px 0}p{color:var(--muted);line-height:1.6}.content{padding:28px 36px}.day{margin-bottom:25px}.day h2{font-size:14px}.slots{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.slot input{position:absolute;opacity:0}.slot span{display:block;text-align:center;padding:12px;border:1px solid var(--line);border-radius:8px;font-weight:600;font-size:13px;cursor:pointer}.slot input:checked+span{border-color:var(--violet);background:var(--soft);color:var(--violet)}.actions{display:flex;justify-content:flex-end;border-top:1px solid var(--line);padding-top:20px}.btn{border:0;border-radius:9px;background:var(--violet);color:#fff;padding:13px 18px;font-weight:700}.notice{padding:16px;border-radius:9px;background:#fff1f3;color:#a33}.success{padding:28px;background:#eefaf5;color:var(--green);border-radius:10px}.success strong{display:block;font-size:20px;margin-bottom:7px}@media(max-width:620px){.hero,.content{padding:24px}.slots{grid-template-columns:repeat(2,1fr)}h1{font-size:27px}}</style></head><body><main class="wrap"><div class="brand">NonceBlox</div><section class="card"><header class="hero"><div class="eyebrow">Interview scheduling</div><h1><?=htmlspecialchars($invitation?'Choose your interview time':'Interview link')?></h1><?php if($invitation):?><p>Hello <?=htmlspecialchars($invitation['candidate_name'])?>. Select one available time for the <strong><?=htmlspecialchars($invitation['job_title'])?></strong> interview. Times are shown in <?=htmlspecialchars($invitation['timezone'])?>.</p><?php endif?></header><div class="content"><?php if($error):?><div class="notice"><?=htmlspecialchars($error)?></div><?php elseif($confirmed):?><div class="success"><strong>Your interview is confirmed.</strong><?=htmlspecialchars(date('l, d F Y \\a\\t g:i A',strtotime($invitation['confirmed_at'])))?> (<?=htmlspecialchars($invitation['timezone'])?>)</div><?php elseif(!$slots):?><div class="notice">No interview times are currently available. Please contact the hiring team.</div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><?php foreach($grouped as $date=>$daySlots):?><section class="day"><h2><?=htmlspecialchars(date('l, d F',strtotime($date)))?></h2><div class="slots"><?php foreach($daySlots as $slot):?><label class="slot"><input type="radio" name="slot_id" value="<?=(int)$slot['id']?>" required><span><?=htmlspecialchars(date('g:i A',strtotime($slot['starts_at'])))?></span></label><?php endforeach?></div></section><?php endforeach?><div class="actions"><button class="btn" onclick="return confirm('Confirm this interview time?')">Confirm interview time</button></div></form><?php endif?></div></section></main></body></html>
